        java.util.regex.Matcher matcher = pattern.matcher(result);
        java.lang.StringBuffer sb = new java.lang.StringBuffer();
        boolean found = false;
        while (matcher.find()) {
            found = true;
            String varName = matcher.group(1);
            String varValue = props.getProperty(varName);
            if (varValue == null) {
