                stackMapTableEntries.putShort(currentFrameOffset[i]);
            }
        }
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Index out of bounds while writing abstract types", e);
    } catch (Exception e) {
        // Wrap any unexpected exception
        throw new RuntimeException("Error while writing abstract types", e);
    }
