@Override
public String readString() throws IOException {
    // Read the length of the string first. A negative length indicates a null value.
    int length;
    try {
        length = in.readInt();
    } catch (IOException e) {
        // Propagate any I/O errors that occur while reading the length.
        throw e;
    }

    if (length < 0) {
        // Convention: negative length means the string is null.
        return null;
    }

    if (length == 0) {
        // Empty string.
        return "";
    }

    // Guard against absurdly large lengths that could cause memory issues.
    if (length > Integer.MAX_VALUE - 8) {
        throw new IOException("String length too large: " + length);
    }

    byte[] bytes = new byte[length];
    try {
        // Read exactly 'length' bytes from the stream.
        in.readFully(bytes);
    } catch (IOException e) {
        // If reading fails, propagate the exception.
        throw e;
    }

    // Decode the byte array using UTF-8 encoding.
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

