public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        if (i + 1 >= len) {
            throw new IllegalArgumentException("Trailing backslash at end of string");
        }
        char next = str.charAt(i + 1);
        switch (next) {
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\\':
                sb.append('\\');
                i++;
                break;
            case 'u':
                // Unicode escape: \uXXXX
                if (i + 6 > len) {
                    throw new IllegalArgumentException("Incomplete Unicode escape sequence");
                }
                int value = 0;
                for (int j = i + 2; j < i + 6; j++) {
                    char hexChar = str.charAt(j);
                    int digit = Character.digit(hexChar, 16);
                    if (digit == -1) {
                        throw new IllegalArgumentException("Invalid hex digit in Unicode escape: " + hexChar);
                    }
                    value = (value << 4) | digit;
                }
                sb.append((char) value);
                i += 5; // skip \uXXXX
                break;
            default:
                if (next >= '0' && next <= '7') {
                    // Octal escape: up to three octal digits
                    int j = i + 1;
                    int octValue = 0;
                    int count = 0;
                    while (j < len && count < 3 && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                        octValue = (octValue << 3) + (str.charAt(j) - '0');
                        j++;
                        count++;
                    }
                    sb.append((char) octValue);
                    i = j - 1;
                } else {
                    throw new IllegalArgumentException("Unknown escape sequence: \\" + next);
                }
                break;
        }
    }
    return sb.toString();
}

