private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // If either set is null, return an empty set to avoid NullPointerException
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }

    // Determine the smaller set to iterate over for efficiency
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger  = set1.size() <= set2.size() ? set2 : set1;

    // Preallocate the result set with an appropriate initial capacity
    Set<V> result = new HashSet<>(Math.min(smaller.size(), larger.size()));

    // Add elements that exist in both sets
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }

    return result;
}

