protected int removeUnusedNodes() {
    try {
        // If the root of the tree is null, nothing to remove
        if (root == null) {
            return 0;
        }

        // If the root itself is inactive, remove the entire tree
        if (!root.isActive()) {
            int removedCount = countNodes(root);
            root = null;
            return removedCount;
        }

        // Otherwise, recursively remove inactive nodes from the children
        return removeFromChildren(root);
    } catch (Exception e) {
        // In case of any unexpected error, return 0 to indicate no nodes were removed
        return 0;
    }
}

private int removeFromChildren(Category parent) {
    int removed = 0;
    java.util.List<Category> children = parent.getChildren();
    if (children == null) {
        return 0;
    }

    java.util.Iterator<Category> it = children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            // Remove the entire subtree rooted at this child
            removed += countNodes(child);
            it.remove();
        } else {
            // Recurse into active child
            removed += removeFromChildren(child);
        }
    }
    return removed;
}

