private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Strip surrounding double quotes if present
    if (input.length() >= 2 && input.charAt(0) == '"' && input.charAt(input.length() - 1) == '"') {
        input = input.substring(1, input.length() - 1);
    }
    StringBuilder sb = new StringBuilder();
    int len = input.length();
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'v':
                    sb.append('\u000B'); // vertical tab
                    i++;
                    break;
                case '"':
                    sb.append('"');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'x':
                    // \xNN: two hex digits
                    if (i + 3 < len) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 3;
                        } catch (NumberFormatException e) {
                            // Invalid hex, treat literally
                            sb.append('\\').append('x');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('x');
                        i++;
                    }
                    break;
                case 'u':
                    // \uNNNN: four hex digits
                    if (i + 5 < len) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 5;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                case 'U':
                    // \UNNNNNNNN: eight hex digits
                    if (i + 9 < len) {
                        String hex = input.substring(i + 2, i + 10);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            // Convert to UTF-16 code units
                            sb.append(Character.toChars(val));
                            i += 9;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('U');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('U');
                        i++;
                    }
                    break;
                default:
                    // Unknown escape, keep the character after backslash
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

