        }
        for (Profile profile : profiles) {
            if (profile == null) {
                continue;
            }
            SegmentSnapshot snapshot = profile.getSegmentSnapshot();
            if (snapshot == null) {
                continue;
            }
            java.util.List<SearchSequence> sequences = snapshot.getSearchSequences();
            if (sequences == null) {
                continue;
            }
            int start = 0;
            for (SearchSequence seq : sequences) {
                if (seq == null) {
                    continue;
                }
                int length = seq.getLength();
                if (length <= 0) {
                    continue;
                }
                ranges.add(new SequenceRange(start, start + length));
                start += length;
            }
        }
    } catch (Exception e) {
        // In case of unexpected errors, return what has been built so far
    }
    return ranges;
}

