private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }

    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    long runningSum = 0L;

    // Compute suffix sums from the end
    for (int i = n - 1; i >= 0; i--) {
        runningSum += bounds.get(i);
        // Cast to int for the suffix list; overflow will wrap as per Java's int behavior
        suffix.add(0, (int) runningSum);
    }

    // The total sum is the last runningSum value
    return new Pair<>(suffix, runningSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    int len = arr.length;
    if (from < 0 || to >= len) {
        throw new IndexOutOfBoundsException(
            "Indices out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException(
            "Invalid range: from (" + from + ") is greater than to (" + to + ")");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is null or empty, nothing to do.
    if (list == null || list.size == 0) {
        return;
    }
    // If the source list is the same as this list, nothing to do.
    if (list == this) {
        return;
    }

    // If this list is empty, simply adopt the source list's nodes.
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link the tail of this list to the head of the source list.
        this.tail.next = list.head;
        list.head.prev = this.tail;
        // Update the tail reference.
        this.tail = list.tail;
    }

    // Update the size of this list.
    this.size += list.size;

    // Clear the source list.
    list.head = null;
    list.tail = null;
    list.size = 0;
}

