public int decide(LoggingEvent event) {
    // Return NEUTRAL if the event itself is null
    if (event == null) {
        return Filter.NEUTRAL;
    }

    // Safely obtain the message from the event
    Object msgObj = null;
    try {
        msgObj = event.getMessage();
    } catch (Exception e) {
        // If retrieving the message throws an exception, treat it as no match
        return Filter.NEUTRAL;
    }

    // If the message is null, there is nothing to match against
    if (msgObj == null) {
        return Filter.NEUTRAL;
    }

    // Convert the message to a string for matching
    String message = msgObj.toString();

    // Perform the string match if a target string is defined
    try {
        // Assume a field named 'stringToMatch' exists in the surrounding class
        if (stringToMatch != null && message.contains(stringToMatch)) {
            // A match was found – accept the event
            return Filter.ACCEPT;
        }
    } catch (Exception e) {
        // Any exception during matching should result in a neutral decision
        return Filter.NEUTRAL;
    }

    // No match found – return NEUTRAL
    return Filter.NEUTRAL;
}

