public static Meteor lookup(HttpServletRequest r){
    if (r == null) {
        return null;
    }
    try {
        // First, try to retrieve from the session if one exists
        HttpSession session = r.getSession(false);
        if (session != null) {
            Object sessionObj = session.getAttribute("meteor");
            if (sessionObj instanceof Meteor) {
                return (Meteor) sessionObj;
            }
        }
        // Next, try to retrieve from the request attributes
        Object requestObj = r.getAttribute("meteor");
        if (requestObj instanceof Meteor) {
            return (Meteor) requestObj;
        }
    } catch (Exception e) {
        // Any exception (e.g., IllegalStateException if session is not allowed)
        // is swallowed and null will be returned
    }
    return null;
}

public static String[] split(String toSplit, String delimiter) {
    // Validate inputs
    if (toSplit == null || delimiter == null || delimiter.isEmpty()) {
        return null;
    }
    // Find the first occurrence of the delimiter
    int idx = toSplit.indexOf(delimiter);
    if (idx == -1) {
        // Delimiter not found
        return null;
    }
    // Extract parts before and after the delimiter
    String before = toSplit.substring(0, idx);
    String after = toSplit.substring(idx + delimiter.length());
    return new String[]{before, after};
}

