public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Validate inputs
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }

    Runnable task = () -> {
        try {
            // Select the row
            table.setRowSelectionInterval(row, row);

            // Scroll to make the row visible
            Rectangle rect = table.getCellRect(row, 0, true);
            if (rect != null) {
                table.scrollRectToVisible(rect);
            }

            // Delay repaint to ensure the row is painted
            SwingUtilities.invokeLater(() -> {
                try {
                    table.repaint();
                } catch (Exception e) {
                    // Ignore repaint failures
                }
            });
        } catch (Exception e) {
            // Ignore selection/scrolling failures
        }
    };

    // Ensure the task runs on the Event Dispatch Thread
    if (SwingUtilities.isEventDispatchThread()) {
        task.run();
    } else {
        SwingUtilities.invokeLater(task);
    }
}

public ByteVector putInt(final int intValue){
    // Ensure the internal buffer is initialized and has enough space
    if (buf == null) {
        buf = new byte[4];
    } else if (length + 4 > buf.length) {
        int newSize = Math.max(buf.length * 2, length + 4);
        byte[] newBuf = new byte[newSize];
        System.arraycopy(buf, 0, newBuf, 0, length);
        buf = newBuf;
    }
    // Write the int in big-endian order
    buf[length++] = (byte)(intValue >> 24);
    buf[length++] = (byte)(intValue >> 16);
    buf[length++] = (byte)(intValue >> 8);
    buf[length++] = (byte)intValue;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // If both references are the same, they are equal
    if (a == b) {
        return true;
    }
    // If either array is null, they cannot be equal
    if (a == null || b == null) {
        return false;
    }
    // Non-positive count means nothing to compare; treat as equal
    if (count <= 0) {
        return true;
    }
    // If count exceeds either array's length, they cannot be equal
    if (count > a.length || count > b.length) {
        return false;
    }
    // Compare byte by byte
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

