private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    // A null or empty set of vertices is trivially a clique
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }
    // Convert to list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();
    for (int i = 0; i < n; i++) {
        V vi = vertexList.get(i);
        if (vi == null) {
            // Null vertex cannot be part of a clique
            return false;
        }
        for (int j = i + 1; j < n; j++) {
            V vj = vertexList.get(j);
            if (vj == null) {
                return false;
            }
            // For undirected graphs, containsEdge checks existence of an edge between vi and vj
            // For directed graphs, this will only check the directed edge vi -> vj
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    if (descriptor.isEmpty()) {
        return;
    }

    // Helper to pop a single type from the stack
    Runnable popOne = () -> {
        if (stack.isEmpty()) {
            throw new IllegalStateException("Stack underflow while popping type");
        }
        stack.pop();
    };

    // If descriptor starts with '(' it's a method descriptor
    if (descriptor.charAt(0) == '(') {
        int end = descriptor.indexOf(')');
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        String args = descriptor.substring(1, end);
        int i = 0;
        while (i < args.length()) {
            // Parse one argument type
            char c = args.charAt(i);
            if (c == '[') {
                // Array type: consume all '['
                while (i < args.length() && args.charAt(i) == '[') {
                    i++;
                }
                if (i >= args.length()) {
                    throw new IllegalArgumentException("Invalid array type in descriptor");
                }
                c = args.charAt(i);
                if (c == 'L') {
                    // Object component type
                    i++; // skip 'L'
                    while (i < args.length() && args.charAt(i) != ';') {
                        i++;
                    }
                    if (i >= args.length()) {
                        throw new IllegalArgumentException("Invalid object type in array component");
                    }
                    i++; // skip ';'
                } else {
                    // Primitive component type
                    i++;
                }
            } else if (c == 'L') {
                // Object type
                i++; // skip 'L'
                while (i < args.length() && args.charAt(i) != ';') {
                    i++;
                }
                if (i >= args.length()) {
                    throw new IllegalArgumentException("Invalid object type in descriptor");
                }
                i++; // skip ';'
            } else {
                // Primitive type
                i++;
            }
            // Pop one type from the stack for this argument
            popOne.run();
        }
    } else {
        // Descriptor is a single type
        int i = 0;
        char c = descriptor.charAt(i);
        if (c == '[') {
            // Array type
            while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid array type descriptor");
            }
            c = descriptor.charAt(i);
            if (c == 'L') {
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                    i++;
                }
                if (i >= descriptor.length()) {
                    throw new IllegalArgumentException("Invalid object type in array descriptor");
                }
                i++; // skip ';'
            } else {
                // Primitive component type
                i++;
            }
        } else if (c == 'L') {
            // Object type
            i++; // skip 'L'
            while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                i++;
            }
            if (i >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid object type descriptor");
            }
            i++; // skip ';'
        } else {
            // Primitive type
            i++;
        }

        if (i != descriptor.length()) {
            throw new IllegalArgumentException("Invalid type descriptor");
        }

        // Void type 'V' is not a valid stack type to pop
        if (descriptor.equals("V")) {
            throw new IllegalArgumentException("Cannot pop void type");
        }

        popOne.run();
    }
}

