private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    try {
        Collections.sort(sorted);
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("All keys must be comparable", e);
    }
    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        int upper;
        try {
            int idx = Collections.binarySearch(sorted, key);
            if (idx < 0) {
                // Insertion point for key
                upper = -idx - 1;
            } else {
                // Find the first element strictly greater than key
                upper = idx;
                while (upper < sorted.size() && ((Comparable<K>)sorted.get(upper)).compareTo(key) <= 0) {
                    upper++;
                }
            }
        } catch (ClassCastException e) {
            throw new IllegalArgumentException("All keys must be comparable", e);
        }
        bounds.add(upper);
    }
    return bounds;
}

