static String[] toNoNullStringArray(Object[] array){
    // Return null if the input array itself is null
    if (array == null) {
        return null;
    }

    // Count non‑null elements
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }

    // If there are no nulls and the array is already a String[], return it directly
    if (nonNullCount == array.length && array instanceof String[]) {
        return (String[]) array;
    }

    // Create a new array to hold the non‑null elements
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            // Attempt to cast to String; if it fails, throw a clear exception
            try {
                result[idx++] = (String) obj;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException(
                    "Element of exclude list is not a String: " + obj, e);
            }
        }
    }
    return result;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // If the threshold is non-positive, consider the metric expired immediately.
    if (expiredThreshold <= 0) {
        return true;
    }

    long currentTime = System.currentTimeMillis();

    // If the provided timestamp is in the future, it cannot be expired yet.
    if (timestamp > currentTime) {
        return false;
    }

    // Determine if the elapsed time since the timestamp exceeds the threshold.
    return (currentTime - timestamp) > expiredThreshold;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    // Handle null inputs
    if (str == null || substring == null) {
        return false;
    }
    // Negative index is invalid
    if (index < 0) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    // If substring is longer than the remaining part of str, cannot match
    if (index > strLen - subLen) {
        return false;
    }
    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

