final ByteVector put11(final int byteValue1, final int byteValue2){
    // Ensure there is enough space for two more bytes
    if (pos + 2 > buf.length) {
        int newCapacity = Math.max(buf.length * 2, pos + 2);
        if (newCapacity < 0) { // overflow protection
            newCapacity = Integer.MAX_VALUE;
        }
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    buf[pos++] = (byte) byteValue1;
    buf[pos++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    try {
        // Validate the byte range values. These fields are assumed to be defined in the surrounding class.
        if (start < 0 || end < start) {
            throw new IllegalArgumentException(
                "Invalid byte range: start=" + start + ", end=" + end);
        }

        StringBuilder sb = new StringBuilder();
        sb.append("bytes ");
        sb.append(start).append('-').append(end);
        sb.append('/');
        sb.append(total > 0 ? total : "*");

        return sb.toString();
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception to avoid silent failures.
        throw new RuntimeException("Failed to build Content-Range header", e);
    }
}
